	dfs(f);
	for(int i=1;i<=n;i++){
		g=max(dis[i],g);
	}
	cout<<g;
	return 0;
} debug"},{"role":"assistant","content":"树的直径可以通过两次DFS找到。以下是代码的逻辑和关键点：

